// Parse Claude's JSON text response out of the Anthropic API envelope.
// Handles markdown code-fence wrapping and processes ALL items (not just item 0).
function extractJson(raw) {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  const cleaned = fenced ? fenced[1] : raw;
  return JSON.parse(cleaned.trim());
}

return items.map(item => {
  const raw = item.json.content[0].text;
  let parsed;
  try {
    parsed = extractJson(raw);
  } catch (e) {
    parsed = { category: 'PARSE_ERROR', is_urgent: true, lead_quality: 'unknown', draft_reply: '', suggested_staff_action: 'Manual review - could not parse AI response: ' + raw };
  }
  return { json: parsed };
});
